from ocean.drone import *

# File: sweep_bay.py
# ------------------
# Pick up every bottle in the bay.


def turn_right():
    turn_left()
    turn_left()
    turn_left()


def clean_square():
    if bottle_present():
        pick_bottle()


def clean_row():
    while front_is_clear():
        clean_square()
        move()
    clean_square()


def go_up_and_turn():
    if facing_east():
        turn_left()
        move()
        turn_left()
    else:
        turn_right()
        move()
        turn_right()


def main():
    for i in range(3):
        clean_row()
        go_up_and_turn()
    clean_row()


if __name__ == '__main__':
    main()
